from pydantic import BaseModel
from typing import List, Dict, Optional

class Card(BaseModel):
    id: str
    name: str
    mana_cost: int
    type: str
    effect: Optional[Dict] = None

class PlayerState(BaseModel):
    name: str
    hand: Optional[List[str]] = None
    mana: Optional[List[str]] = None
    mana_spend: Optional[int] = 0
    deck: Optional[List[str]] = None
    discard: Optional[List[str]] = None
    current_position: Optional[int] = 0
    message: Optional[Dict] = None
    messages_history: List[Dict] = []
    action_chain: List[Dict] = []    # a list of dict of cards send by player
    dwelling: Optional[str] = None  # dwelling (engine_version 12: card_id of the dwelling card on the board, e.g. the engineers' refinery)
    dwelling_slot: Optional[int] = None  # dwelling (engine_version 12): the stopover column (0-4) where the placeholder renders (set at placement time: engine_version 15 = the next position in the player's OWN chain (ge._player_stopover), 14 = the k-th FREE stopover (shared skip rule, ge._next_free_stopover_v14), < 14 = the k-th column; cleared in the cleaning phase so the placeholder only shows during the placement turn)
    dwelling_tapped: bool = False   # dwelling (engine_version 12): the dwelling card was already tapped this turn (1 tap/turn, untapped in the cleaning phase)
    play_count: int = 0            # stopover positions (engine_version 15): number of plays (move/defend/dwelling) this player has made THIS turn — the (play_count+1)-th play takes position (rooted count) + play_count + 1 in that player's OWN chain; reset to 0 in the cleaning phase. engine_version 28: a wrecking_ball that removes the player's dwelling card does NOT touch play_count (the placeholder's consumed position stays consumed — the placeholder STAYS in place and the next play lands after it; games < 28 kept the placeholder's position consumed too, but the placeholder itself vanished with the card — the "stopover hole")
    landmine_blocked: bool = False  # landmine (engine_version 12): blocked by a landmine drop until the end of the current turn (move cards canceled — no effect, no advancing — except unstoppable)
    faction: Optional[str] = None  # main faction of the player (e.g. "Dwarves", "Demons", …) — derived from the deck at game creation; public info (needed for biome conditions + placeholder art)
    pendings: List[str] = []        # pending effects
    pending_slots: List = []   # doctors (engine_version 16): the PENDING PLACEHOLDERS currently showing — a per-turn display list (cleared in the cleaning phase, so it is NOT parallel to the persistent `pendings` zone). engine_version 20: when the attached pending card was placed THIS turn, its [card_name, slot] pair STAYS (the placeholder marks the consumed trip-chain position — v19 and below removed it on attachment, which freed the position and desynced the frontend's next-slot mirror). v19: each entry is a [card_name, slot] pair — attachment removed the pair BY CARD NAME (the old index-splice deleted the wrong placeholder once pendings and pending_slots diverged across turns). Legacy entries (bare int slot, v16-18; None = no placeholder, v18 lab tap) are still accepted by every reader. engine_version 18: the laboratory TAP's 'epo' got a None entry (no placeholder); v19+: it gets no entry at all

class GameState(BaseModel):
    id: str
    players: Dict[str, PlayerState] = None      # refers to PlayerState model
    turn_order: List[str] = []                  # list of players names in turn order (this is automatically set in game engine)
    turn: int = 1
    state: str = "waiting for 2nd player"
    message: Optional[Dict] = None
    earth: Optional[List[List[str]]] = []   # a list of token's list for every position
    drop_tokens: Dict[int, int] = {}        # pet_trap (engine_version 8): cell index -> number of drop tokens on that cell (triggered when any player token arrives on the cell)
    winner: Optional[str] = None
    first_player_passed: bool = False
    second_player_passed: bool = False
    temperature: Optional[int] = None        # planet temperature, rolled with a die at game start (can be changed by a Mages thermic_flux card, engine_version 24 — clamped to 1..20)
    temperature_initial: Optional[int] = None  # the temperature rolled at game start (never changed). Lets the replay evaluate temp_* conditions correctly for games with a thermic_flux (the stored `temperature` is the FINAL value, which would be wrong for a temp_* condition resolved BEFORE the change). None for old games (< 24) — the replay falls back to the stored `temperature`.
    day_night: Optional[str] = None          # "day" (card face up) or "night" (card face down), drawn at game start
    day_night_fixed: bool = False            # Celestial_reversal (Mages, engine_version 22): True once a Celestial_reversal card has been played — the day/night is then FIXED (set to the player's chosen value) for the rest of the game and no longer flips each turn (the cleaning phase skips the flip). Default False so old games (< 22) keep flipping as before
    nobodymoves_active: bool = False         # nobodymoves (Mages, engine_version 23): True while the current turn's MOVEMENT is LOCKED — set at play time (an INSTANT effect) when a nobodymoves card is played, cleared in the cleaning phase. While True, ALL players' MOVE cards still RESOLVE (condition checked + non-movement effects fire + defend/block race happens) but their MOVEMENT is suppressed: no basic advancing, no movement effects (advancing/backward/jump/advancing_oppo/backward_oppo/avalanche), no pending epo/virus, no grappling/copy copies; the only exception is an "unstoppable" card whose condition is met, which still moves; DEFEND cards are unaffected. Default False so old games (< 23) keep the old behavior (nobodymoves is a no-op, no lock)
    cataclysm_pile: Optional[List[str]] = None  # cataclysm pile: one card per biome (top = first element), rotated on every cataclysm trigger
    earth_rotation: int = 0                      # black_hole (Mages, engine_version 26): the CUMULATIVE rotation of the earth in CELLS (signed: clockwise positive, counter-clockwise negative — the direction is chosen per tap). Drives the frontend background CSS (transform: rotate(earth_rotation * 15deg), transform-origin: center; 1 cell = 15deg since the board is 24 cells / 360deg) and is the rotation log the replay reconstructs from. 0 for old games (< 26) — the earth never rotates.
    earth_initial_b0: Optional[str] = None       # black_hole (Mages, engine_version 26): the biome of cell 0 (the top) at game init — the base for the background art (the frontend pins the base image to this and ROTATES it by earth_rotation * 15deg, so the art tracks the engine's rotated biome positions instead of jumping to a new image). Set at game init (earth[0][0]). None for old games (< 26) — the frontend falls back to the current cell-0 biome (the pre-rotation behavior).
    engine_version: Optional[int] = None     # rules version the game is played with (24 = + Mages support faction, third card: thermic_flux — an INSTANT play-time effect: the player CHOOSES +4 or −4 °C (message 'temp_change': 'up' or 'down') and the planet temperature changes by that amount, CLAMPED to 1..20, PERMANENTLY (game.temperature mutated at play time — cannot be blocked/canceled/conditioned); the card resolves as a no-op on the trip chain (occupies a stopover position, costs its mana_cost). temperature_initial records the value rolled at game start (for the replay). Games < 24 keep the old behavior — thermic_flux is a no-op and the temperature never changes. 23 = + Mages support faction, second card: nobodymoves — an INSTANT play-time effect: it LOCKS ALL PLAYERS' MOVEMENT for the rest of the turn (their MOVE cards still RESOLVE — condition checked + non-movement effects like draw/ramp/discard/taxation fire + the defend/block race happens — but their basic advancing + movement effects + pending epo/virus + grappling/copy copies are SUPPRESSED; the only exception is an "unstoppable" card whose condition is met, which still moves; DEFEND cards unaffected); game-level flag nobodymoves_active set at play time (cannot be blocked/canceled/conditioned) and cleared in the cleaning phase; the card resolves as a no-op on the trip chain (occupies a stopover position, costs its mana_cost). Games < 23 keep the old behavior — nobodymoves is a no-op and there is no lock. 22 = + Mages support faction, first card: Celestial_reversal — an INSTANT play-time effect: the player CHOOSES day or night (message 'day_night') and it is FIXED (game.day_night set to the choice, game.day_night_fixed = True) for the rest of the game — the day/night no longer flips each turn; the card is played on the trip chain and resolves as a no-op (occupies a stopover position, costs its mana_cost). Games < 22 keep the old behavior — Celestial_reversal is a no-op and the day/night still flips. 21 = + the `pending` CONDITION is implemented - met iff the player has at least one pending card in their OWN pending zone (the doctors' pending zone); games < 21 keep the canonical default (unimplemented -> met). 20 = + the placeholder of a pending card ATTACHED to a main card this same turn STAYS IN PLACE (≤19 removed it on attachment — the freed position desynced the frontend's next-slot suggestion, which offered the main card's own slot for the next play); 19 = + pending_slots is a list of [card, slot] pairs — pending placeholders are a per-turn display list (cleared each turn) NOT parallel to the persistent `pendings` zone, so attachment removed the placeholder BY CARD NAME (≤18 spliced by index in `pendings`, which deleted the WRONG placeholder once the lists diverged across turns — game 26_09_17_21_33_39_d5oEd turn 4); the laboratory TAP's 'epo' gets no slot entry; all readers normalize the legacy bare-int/None shapes. 18 = + the laboratory TAP is a QUICK action with NO trip-chain placeholder — the tap's 'epo' pending card gets a None entry in pending_slots (no placeholder, no position consumed); games 16-17 keep the old behavior (the tap's 'epo' occupied a position). 17 = + board-furniture PLACEHOLDERS (doctor pending cards / dwelling cards) OCCUPY a trip-chain position: ge._player_chain includes them as empty 'placeholder' entries at their recorded stopover position (position = 5 - column), so a grappling_hook / copy_effect facing a placeholder faces an EMPTY position and copies NOTHING - the trip chain matches the board display. Games < 17 keep the legacy chain (placeholders excluded, plays renumbered densely). 16 = + Doctors support faction: 4 pending cards (epo/virus/bloodtest/mercurochrome) + laboratory dwelling; pending zone (to: 'pending_zone'), attachment to a main card (pendings: [name], effect fires when the main card's condition is met), laboratory tap adds an 'epo' pending card. 15 = + PER-PLAYER stopovers: each player has their OWN 5 stopover slots (position 1..5, columns 4,3,2,1,0). A player's rooted cards occupy the LEADING positions of that player's OWN trip chain (position 1, 2, …), and the player's plays go AFTER them (position R+1, …). A player's rooted cards never shift the opponent's positions. Rooted cards on the trip chain are NORMAL cards that apply only their basic advancing (no condition, no effect, but BLOCKABLE by the opponent's defend at the same position). Facing/blocking/grappling/copy are all by per-player position number. ge._player_stopover / ge._player_chain are the single source of truth; the robot (ai_driver) calls them directly and the frontend mirrors them. 14 = + stopover-skip rule (SHARED stopover, superseded by 15's per-player model): a stopover RESERVED by board furniture (a rooted-on-board card or a dwelling placeholder) is SKIPPED by the next play of either player (ge._next_free_stopover_v14); games < 14 keep the legacy plain convention (k-th column, no skip); 13 = + discard selection: discard / discard_oppo effects PAUSE the trip chain and the discarding player CHOOSES the card(s) (to: 'discard_pile'); 12 = + Engineers support faction: 4 drop cards (boost/trampoline/gluetrap/landmine) + refinery dwelling (tap 1x/turn to draw 1) + support cards cost their mana_cost; 11 = + wrecking_ball effect (INSTANT: removes the opponent's dwelling card); 10 = + rooted effect (card survives the cleaning phase on a stopover, one-shot, 1-turn cooldown); 9 = + drop_on_board condition (any drop/trap on the earth); 8 = + pet_trap effect / drop tokens / INSTANT play-time effects; 7 = + copy_effect effect; 6 = + effect_canceled effect; 5 = + grappling_hook effect; 4 = + avalanche effect; 3 = + cataclysm condition; 2 = faction biome bonus + conditional block effect)
    rooted_on_board: List[Dict] = []        # rooted (engine_version 10): cards sitting on a stopover from a previous turn's rooted effect: [{card_id, owner, stopover}]; discarded at the end of the FOLLOWING turn
    rooted_this_turn: List[Dict] = []       # rooted (engine_version 10): cards that earned a rooted token THIS turn (awaiting the end-of-turn placement onto a free stopover): [{card_id, owner}]
    rooted_history: Dict[str, int] = {}     # rooted (engine_version 10): card_id -> last turn it earned a rooted token (1-turn cooldown: cannot earn another the very next turn)
    board_drops: List[Dict] = []            # engineers (engine_version 12): drop tokens on the board (boost/trampoline/gluetrap/landmine): [{cell, kind, owner}]; each fires once when ANY token arrives on its cell, then is consumed
    log: List[Dict] = []                    # turn log (PUBLIC info only): one entry per turn -> 'instant' (list of {player, what}: the play-time instant effects + dwelling taps of the turn — pet_trap, engineer drops, wrecking_ball, the Mages' instant cards, refinery/laboratory/black_hole taps — rendered at the TOP of the turn, before the stopovers; old games have no 'instant' key) + 'stopovers' -> per player: card, condition met, effect, negative effects (blocked/canceled...), notes (cataclysm, grappling copy...), positions
    pending_discard: Optional[Dict] = None  # discard selection (engine_version 13): the trip chain is PAUSED waiting for the discarding player's choice: {player, n}; consumed by the to:'discard_pile' message (None when the chain is not paused)
    chain_resume: Optional[Dict] = None     # discard selection (engine_version 13): the trip chain's resume context (index, stage, log entries, per-player flags) saved by process_trip_chain when it pauses; cleared when the chain resumes

    def to_json(self) -> str:
        return self.model_dump_json()

    @classmethod
    def from_json(cls, data: str) -> "GameState":
        return cls.model_validate_json(data)
